package ssmcert

// script is the on-box program: `load` (the in-service step) and `check`
// (the timer). Every value read from SSM goes from the CLI's JSON straight
// into its file through python3's stdin; none is ever printed or logged.
const script = `#!/bin/bash
# asg-ssmcert: a certificate, its key and a CA bundle from SSM Parameter
# Store into files under /run, and a rotation inside a nightly window for a
# daemon that loads them only at start. Generated by
# github.com/truvity/asg/modules/ssmcert.
#
#   load   read the parameters into DIR and record their versions
#   check  compare the recorded versions with the current ones; on a change,
#          rotate if the window is open
set -uo pipefail

# shellcheck disable=SC1090
. "${ASG_SSMCERT_CONF:?ASG_SSMCERT_CONF names the configuration}"

READY="${ASG_SSMCERT_READY:-/etc/asg/ssmcert-${NAME}-ready.sh}"
WATCHDOG_STATE="${ASG_WATCHDOG_STATE:-/run/asg-watchdog}"
POLL="${ASG_SSMCERT_POLL:-10}"

log() { printf '%s asg-ssmcert[%s]: %s\n' "$(date -u '+%Y-%m-%dT%H:%M:%SZ')" "$NAME" "$*" >&2; }

imds() {
  local t
  t="$(curl -fsS -m 5 -X PUT -H 'X-aws-ec2-metadata-token-ttl-seconds: 300' http://169.254.169.254/latest/api/token)" || return 1
  curl -fsS -m 5 -H "X-aws-ec2-metadata-token: $t" "http://169.254.169.254/latest/meta-data/$1"
}

REGION=""
region() {
  [ -n "$REGION" ] || REGION="$(imds placement/region)" || { log "no region from the instance metadata"; return 1; }
}

params() {
  printf '%s cert.pem 0644\n%s key.pem 0600\n' "$CERT_PARAM" "$KEY_PARAM"
  [ -z "$CA_PARAM" ] || printf '%s ca.pem 0644\n' "$CA_PARAM"
}

# load reads every parameter (decrypted) into a new directory beside DIR and
# swaps it in, so a reader never sees half a set.
load() {
  region || return 1
  umask 077
  local parent tmp param file mode out v i
  parent="$(dirname "$DIR")"
  install -d -m 0755 "$parent" || return 1
  tmp="$(mktemp -d "$parent/.ssmcert-$NAME.XXXXXX")" || return 1
  : >"$tmp/versions"
  while read -r param file mode; do
    out=""
    for i in 1 2 3 4 5; do
      if out="$(aws ssm get-parameter --region "$REGION" --name "$param" --with-decryption --output json)" && [ -n "$out" ]; then
        break
      fi
      out=""
      sleep $((i * 3))
    done
    if [ -z "$out" ]; then
      log "cannot read $param"
      rm -rf "$tmp"
      return 1
    fi
    if ! v="$(printf '%s' "$out" | python3 -c 'import json,sys
p = json.load(sys.stdin)["Parameter"]
with open(sys.argv[1], "w") as f:
    f.write(p["Value"])
print(p["Version"])' "$tmp/$file")"; then
      out=""
      log "cannot parse $param"
      rm -rf "$tmp"
      return 1
    fi
    out=""
    chmod "$mode" "$tmp/$file"
    printf '%s %s\n' "$param" "$v" >>"$tmp/versions"
  done < <(params)
  chmod 0644 "$tmp/versions"
  chmod 0700 "$tmp"
  [ -z "$OWNER" ] || chown -R "$OWNER" "$tmp" || { rm -rf "$tmp"; return 1; }
  if [ -e "$DIR" ]; then
    rm -rf "$DIR.old"
    mv "$DIR" "$DIR.old" || { rm -rf "$tmp"; return 1; }
  fi
  mv "$tmp" "$DIR" || return 1
  rm -rf "$DIR.old"
  log "loaded $(tr '\n' ' ' <"$DIR/versions")"
}

in_window() {
  local h
  h=$((10#${ASG_SSMCERT_HOUR:-$(date -u +%H)}))
  if [ "$WINDOW_START" -lt "$WINDOW_END" ]; then
    [ "$h" -ge "$WINDOW_START" ] && [ "$h" -lt "$WINDOW_END" ]
  else
    [ "$h" -ge "$WINDOW_START" ] || [ "$h" -lt "$WINDOW_END" ]
  fi
}

connections() { ss -Htn state established "( sport = :$DRAIN_PORT )" | wc -l; }

# pause_watchdog keeps the watchdog from acting while the daemon restarts
# on purpose (watchdog >= v0.4.0 honours paused-until).
pause_watchdog() {
  mkdir -p "$WATCHDOG_STATE"
  echo $(($(date +%s) + $1)) >"$WATCHDOG_STATE/paused-until"
}
resume_watchdog() { rm -f "$WATCHDOG_STATE/paused-until" "$WATCHDOG_STATE/unhealthy-since"; }

restart_and_wait() {
  load || return 1
  log "restarting ${RESTART_UNITS[*]}"
  systemctl restart "${RESTART_UNITS[@]}" || return 1
  local deadline=$((SECONDS + READY_TIMEOUT))
  until bash "$READY" >/dev/null 2>&1; do
    if [ "$SECONDS" -ge "$deadline" ]; then
      log "not ready after ${READY_TIMEOUT}s"
      return 1
    fi
    sleep "$POLL"
  done
  log "ready with the new certificate"
}

rotate_in_place() {
  local idle=0 deadline=$((SECONDS + 3000))
  while [ "$idle" -lt "$IDLE_SECONDS" ]; do
    if [ "$SECONDS" -ge "$deadline" ] || ! in_window; then
      log "no idle period of ${IDLE_SECONDS}s; trying again at the next check"
      return 0
    fi
    if [ "$(connections)" -eq 0 ]; then idle=$((idle + POLL)); else idle=0; fi
    sleep "$POLL"
  done
  pause_watchdog $((READY_TIMEOUT + 300))
  if restart_and_wait; then
    resume_watchdog
    return 0
  fi
  resume_watchdog
  return 1
}

# group prints: desired max in-service-others busy-others self-state.
group() {
  aws autoscaling describe-auto-scaling-groups --region "$REGION" --auto-scaling-group-names "$GROUP" --output json |
    python3 -c 'import json,sys
g = json.load(sys.stdin)["AutoScalingGroups"][0]
me = sys.argv[1]
others = [i for i in g["Instances"] if i["InstanceId"] != me]
mine = [i["LifecycleState"] for i in g["Instances"] if i["InstanceId"] == me]
ins = sum(1 for i in others if i["LifecycleState"] == "InService")
busy = sum(1 for i in others if i["LifecycleState"] != "InService")
print(g["DesiredCapacity"], g["MaxSize"], ins, busy, mine[0] if mine else "Gone")' "$IID"
}

# leave_standby returns the instance to service, completes the launch hook
# that ExitStandby runs again, and sets the desired capacity back to before.
leave_standby() {
  local before="$1" d m ins busy state deadline
  aws autoscaling exit-standby --region "$REGION" --auto-scaling-group-name "$GROUP" --instance-ids "$IID" >/dev/null ||
    { log "exit-standby failed"; return 1; }
  deadline=$((SECONDS + 900))
  while :; do
    read -r d m ins busy state < <(group) || state=""
    case "$state" in
      InService) break ;;
      Pending:Wait)
        aws autoscaling complete-lifecycle-action --region "$REGION" --auto-scaling-group-name "$GROUP" \
          --lifecycle-hook-name "$HOOK" --instance-id "$IID" --lifecycle-action-result CONTINUE >/dev/null 2>&1 || true
        ;;
    esac
    if [ "$SECONDS" -ge "$deadline" ]; then
      log "not back in service after 15 minutes (state '$state')"
      return 1
    fi
    sleep "$POLL"
  done
  read -r d m ins busy state < <(group) || return 1
  if [ "$d" -eq $((before + 1)) ]; then
    log "back in service; desired capacity $d -> $before (the termination policy picks who leaves)"
    aws autoscaling set-desired-capacity --region "$REGION" --auto-scaling-group-name "$GROUP" --desired-capacity "$before" >/dev/null ||
      { log "set-desired-capacity failed"; return 1; }
  else
    log "back in service; desired capacity is $d, not $((before + 1)): left as it is"
  fi
}

rotate_standby() {
  local d m ins busy state deadline
  IID="$(imds instance-id)" || { log "no instance id"; return 1; }
  read -r d m ins busy state < <(group) || { log "cannot describe $GROUP"; return 1; }
  if [ "$state" != InService ] || [ "$busy" -ne 0 ] || [ "$ins" -lt $((d - 1)) ] || [ "$d" -ge "$m" ]; then
    log "group busy or full (desired $d, max $m, others in service $ins, others busy $busy, self $state); trying again at the next check"
    return 0
  fi
  pause_watchdog $((REPLACEMENT_SECONDS + DRAIN_SECONDS + READY_TIMEOUT + 1200))
  log "entering Standby; the group puts a replacement in service"
  if ! aws autoscaling enter-standby --region "$REGION" --auto-scaling-group-name "$GROUP" --instance-ids "$IID" \
    --no-should-decrement-desired-capacity >/dev/null; then
    log "enter-standby failed"
    resume_watchdog
    return 1
  fi
  deadline=$((SECONDS + REPLACEMENT_SECONDS))
  while :; do
    read -r _ _ ins busy state < <(group) || state=""
    [ "$state" = Standby ] && [ "$ins" -ge "$d" ] && break
    if [ "$SECONDS" -ge "$deadline" ]; then
      log "no replacement in service after ${REPLACEMENT_SECONDS}s; leaving Standby without a restart"
      leave_standby "$d"
      resume_watchdog
      return 1
    fi
    sleep "$POLL"
  done
  deadline=$((SECONDS + DRAIN_SECONDS))
  until [ "$(connections)" -eq 0 ] || [ "$SECONDS" -ge "$deadline" ]; do sleep "$POLL"; done
  log "$(connections) connection(s) left on :$DRAIN_PORT"
  if ! restart_and_wait; then
    log "the restart failed; terminating this instance, the replacement keeps serving"
    aws autoscaling terminate-instance-in-auto-scaling-group --region "$REGION" --instance-id "$IID" \
      --no-should-decrement-desired-capacity >/dev/null || log "terminate failed"
    return 1
  fi
  leave_standby "$d"
  local rc=$?
  resume_watchdog
  return "$rc"
}

check() {
  region || return 1
  [ -s "$DIR/versions" ] || { log "nothing loaded yet ($DIR/versions)"; return 1; }
  local param ver cur changed=0
  while read -r param ver; do
    cur="$(aws ssm get-parameter --region "$REGION" --name "$param" --query Parameter.Version --output text)" ||
      { log "cannot read the version of $param"; return 1; }
    if [ "$cur" != "$ver" ]; then
      log "$param: version $ver loaded, $cur current"
      changed=1
    fi
  done <"$DIR/versions"
  [ "$changed" = 1 ] || return 0
  if ! in_window; then
    log "a new version waits for the window ($WINDOW_START:00-$WINDOW_END:00 UTC)"
    return 0
  fi
  if [ "$STANDBY" = 1 ]; then rotate_standby; else rotate_in_place; fi
}

case "${1:-}" in
  load) load ;;
  check) check ;;
  *)
    echo "usage: $0 load|check" >&2
    exit 2
    ;;
esac
`
